//! The embedded sound bank. The data itself lives in `bank.rs` generated by
//! `build.rs` from `assets/sounds/manifest.json`; this module only declares
//! the types that generated code uses and a few lookup helpers.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    /// Plays forever until stopped; has a volume slider.
    Loop,
    /// Fires once (a stinger such as a thunderclap or a sword clash).
    OneShot,
}

pub struct SoundDef {
    pub id: &'static str,
    pub name: &'static str,
    pub category: &'static str,
    pub kind: Kind,
    pub bytes: &'static [u8],
    pub author: &'static str,
    pub license: &'static str,
    pub source: &'static str,
    pub desc: &'static str,
}

pub struct Category {
    pub name: &'static str,
    pub desc: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/bank.rs"));

pub fn find(id: &str) -> Option<&'static SoundDef> {
    SOUNDS.iter().find(|s| s.id == id)
}

pub fn in_category<'a>(name: &'a str) -> impl Iterator<Item = &'static SoundDef> + 'a {
    SOUNDS.iter().filter(move |s| s.category == name)
}
